#!/usr/bin/env python3
"""Properly extract text from FINAL BOOST sections including tables/textboxes."""
import xml.etree.ElementTree as ET
import json
import re

tree = ET.parse('/tmp/pabu/Contents/section0.xml')
root = tree.getroot()
NS_HP = 'http://www.hancom.co.kr/hwpml/2011/paragraph'

def get_all_text(el):
    """Get all text content under this element, joining in document order."""
    texts = []
    for t in el.iter(f'{{{NS_HP}}}t'):
        if t.text:
            texts.append(t.text)
    return ''.join(texts)

# For each top-level <hp:p>, get its full text (including nested)
# But also note that there are <hp:p> nested inside tables/textboxes — we need to be careful
# Approach: collect only direct children <hp:p> of <hs:sec> (top-level), and for each,
#          gather all text from itself + descendants

ns_sec = 'http://www.hancom.co.kr/hwpml/2011/section'
top_paragraphs = list(root.findall(f'{{{NS_HP}}}p'))
print(f"Top-level paragraphs: {len(top_paragraphs)}")

# Build items list with (idx, paraPrIDRef, full_text, has_table)
items = []
for i, p in enumerate(top_paragraphs):
    pidx = p.get('paraPrIDRef', '?')
    full_text = get_all_text(p).replace('\n', ' ').strip()
    has_table = p.find(f'.//{{{NS_HP}}}tbl') is not None
    has_drawtext = p.find(f'.//{{{NS_HP}}}drawText') is not None
    if full_text:
        items.append({
            'idx': i, 'style': pidx, 'text': full_text,
            'has_table': has_table, 'has_drawtext': has_drawtext
        })

print(f"Items with text: {len(items)}")

# Find FINAL BOOST section starts
boost_starts = {}
for i, it in enumerate(items):
    m = re.match(r'^FINAL BOOST (\d+)\s*$', it['text'])
    if m:
        n = int(m.group(1))
        if n not in boost_starts and 1 <= n <= 31:
            boost_starts[n] = i

# For each section, find the content range
sorted_starts = sorted(boost_starts.items())
sections = {}
for idx, (n, start_idx) in enumerate(sorted_starts):
    if idx + 1 < len(sorted_starts):
        next_start = sorted_starts[idx + 1][1]
    else:
        next_start = len(items)
        for j in range(start_idx, len(items)):
            if '파이널 부스트 답안' in items[j]['text']:
                next_start = j
                break
    section_items = items[start_idx:next_start]
    end = len(section_items)
    for j, it in enumerate(section_items):
        if 'SELF CHECK LIST' in it['text']:
            end = j
            break
    sections[n] = section_items[:end]

# Save
with open('/tmp/pabu_sections_full.json', 'w', encoding='utf-8') as f:
    json.dump({str(n): s for n, s in sections.items()}, f, ensure_ascii=False, indent=2)

print(f"Sections: {len(sections)}")
print("\n=== Section 4 (레이저 냉각) full content ===")
for it in sections[4]:
    print(f"  s={it['style']:3} | {it['text'][:300]}")

